solutions.naive:
class Solution:
    def maxRunTime(self, n: int, batteries: list[int]) -> int:
        limit = sum(batteries) // n
        ans = 0
        for t in range(limit + 1):
            if sum(min(b, t) for b in batteries) >= n * t:
                ans = t
            else:
                break
        return ans

