class Solution:
    def maxRunTime(self, n: int, batteries: list[int]) -> int:
        lo, hi = 0, sum(batteries) // n
        while lo <= hi:
            mid = (lo + hi) // 2
            if sum(min(b, mid) for b in batteries) >= n * mid:
                lo = mid + 1
            else:
                hi = mid - 1
        return hi

solutions.optimal:
class Solution:
    def maxRunTime(self, n: int, batteries: list[int]) -> int:
        batteries.sort()
        total = sum(batteries)
        while batteries and batteries[-1] > total // n:
            total -= batteries.pop()
            n -= 1
        return total // n

